library(tidyverse)
library(glue)

wada &lt;- read_csv("../data/sanzo_wada_colors_long.csv")

swatch_html &lt;- function(hex, name, cap = 8) {
  n &lt;- length(hex)
  hex &lt;- head(hex, cap)
  name &lt;- head(name, cap)
  spans &lt;- glue('&lt;span class="mini-swatch" style="background:{hex}" title="{name}"&gt;&lt;/span&gt;')
  out &lt;- paste(spans, collapse = "")
  if (n &gt; cap) out &lt;- paste0(out, glue('&lt;span class="palette-module-more"&gt;+{n - cap} more&lt;/span&gt;'))
  out
}

# a base color's combo size is itself + however many colors Wada matched to
# it (one row per match) -- see R/prep-wada.R for the same logic documented
# and validated outside the render path
wada_bases &lt;- wada |&gt;
  group_by(color_name) |&gt;
  summarise(color_hex = first(color_hex), n_matches = n(), .groups = "drop") |&gt;
  mutate(combo_size = n_matches + 1)

gallery &lt;- wada_bases |&gt;
  filter(combo_size %in% 2:4) |&gt;
  group_by(combo_size) |&gt;
  summarise(
    n_combos = n(),
    examples = paste(head(color_name, 4), collapse = ", "),
    swatches = swatch_html(color_hex, color_name),
    .groups = "drop"
  ) |&gt;
  arrange(combo_size) |&gt;
  mutate(label = glue("{combo_size}-color combo"))

cat(
  '&lt;div class="palette-gallery"&gt;',
  glue_data(
    gallery,
    '&lt;div class="palette-module"&gt;
  &lt;h4&gt;{label} &lt;span class="palette-module-count"&gt;{n_combos} combos&lt;/span&gt;&lt;/h4&gt;
  &lt;p class="palette-module-desc"&gt;e.g. {examples}&lt;/p&gt;
  &lt;div class="palette-module-swatches"&gt;{swatches}&lt;/div&gt;
&lt;/div&gt;'
  ),
  '&lt;/div&gt;',
  sep = "\n"
)




