library(tidyverse)
library(glue)

aggieland &lt;- read_csv("../data/aggieland-colors.csv")

swatch_html &lt;- function(hex, name, cap = 8) {
  n &lt;- length(hex)
  hex &lt;- head(hex, cap)
  name &lt;- head(name, cap)
  spans &lt;- glue('&lt;span class="mini-swatch" style="background:{hex}" title="{name}"&gt;&lt;/span&gt;')
  out &lt;- paste(spans, collapse = "")
  if (n &gt; cap) out &lt;- paste0(out, glue('&lt;span class="palette-module-more"&gt;+{n - cap} more&lt;/span&gt;'))
  out
}

gallery &lt;- aggieland |&gt;
  group_by(palette) |&gt;
  summarise(
    n_colors = n(),
    palette_name = first(display_name),
    examples = paste(head(hex, 4), collapse = ", "),
    swatches = swatch_html(hex, display_name),
    .groups = "drop"
  ) |&gt;
  arrange(palette)

cat(
  '&lt;div class="palette-gallery"&gt;',
  glue_data(
    gallery,
    '&lt;div class="palette-module"&gt;
  &lt;h4&gt;{palette_name} &lt;span class="palette-module-count"&gt;{n_colors} colors&lt;/span&gt;&lt;/h4&gt;
  &lt;p class="palette-module-desc"&gt;e.g. {examples}&lt;/p&gt;
  &lt;div class="palette-module-swatches"&gt;{swatches}&lt;/div&gt;
&lt;/div&gt;'
  ),
  '&lt;/div&gt;',
  sep = "\n"
)




